const cfg = $('⚙️ Configurações').first().json;

const fmtPG = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
const fmtLabel = (d) => String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear();
const parseYMD = (str) => {
  const parts = str.split('-').map(Number);
  return new Date(parts[0], parts[1] - 1, parts[2]);
};
const fmtLabelStr = (ymdStr) => {
  const parts = ymdStr.split('-');
  return `${parts[2]}/${parts[1]}/${parts[0]}`;
};

let start_date, end_date, start_date_ant, end_date_ant, dataRef, dataRefAnt;

const hasCustom = cfg.data_inicio_custom && typeof cfg.data_inicio_custom === 'string' && cfg.data_inicio_custom.trim() !== '' &&
                  cfg.data_fim_custom && typeof cfg.data_fim_custom === 'string' && cfg.data_fim_custom.trim() !== '';

if (hasCustom) {
  start_date = cfg.data_inicio_custom.trim();
  end_date = cfg.data_fim_custom.trim();
  const dStart = parseYMD(start_date);
  const dEnd = parseYMD(end_date);
  const diffTime = Math.abs(dEnd - dStart);
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
  const shiftDays = diffDays > 0 ? diffDays : 7;

  const dStartAnt = new Date(dStart);
  dStartAnt.setDate(dStart.getDate() - shiftDays);
  const dEndAnt = new Date(dEnd);
  dEndAnt.setDate(dEnd.getDate() - shiftDays);

  start_date_ant = fmtPG(dStartAnt);
  end_date_ant = fmtPG(dEndAnt);
  dataRef = fmtLabelStr(start_date) + ' a ' + fmtLabelStr(end_date);
  dataRefAnt = fmtLabel(dStartAnt) + ' a ' + fmtLabel(dEndAnt);
} else {
  // Regra Oficial: Execução na Terça-feira com Fechamento de Segunda a Segunda
  const agora = new Date();
  const dow = agora.getDay(); // 0=Dom, 1=Seg, 2=Ter, 3=Qua, 4=Qui, 5=Sex, 6=Sab

  // Se rodar na terça (dow=2), a segunda de ontem (fim da semana) = recuo de 1 dia
  const recuoFim = (dow === 1 ? 7 : (dow === 2 ? 1 : (dow === 0 ? 6 : dow - 1)));

  const fim = new Date(agora);
  fim.setDate(agora.getDate() - recuoFim);

  const inicio = new Date(fim);
  inicio.setDate(fim.getDate() - 7);

  const inicioAnt = new Date(inicio);
  inicioAnt.setDate(inicio.getDate() - 7);

  const fimAnt = new Date(inicio);

  start_date = fmtPG(inicio);
  end_date = fmtPG(fim);
  start_date_ant = fmtPG(inicioAnt);
  end_date_ant = fmtPG(fimAnt);
  dataRef = fmtLabel(inicio) + ' a ' + fmtLabel(fim);
  dataRefAnt = fmtLabel(inicioAnt) + ' a ' + fmtLabel(fimAnt);
}

return [{
  json: {
    start_date,
    end_date,
    start_date_ant,
    end_date_ant,
    dataRef,
    dataRefAnt,
    modo_producao: cfg.modo_producao,
    email_teste: cfg.email_teste,
    top_pracas: cfg.top_pracas
  }
}];

// ===========================================================================
// Gerar HTML + CSV — Pedágio Semanal por Filial
// Mesma familia visual do combustivel: cabecalho TruckPag (faixa topografica
// + logo oficial via anexo inline CID) e RODAPE padrao Gritsch, igual ao do
// rastreador. Dado tambem vem do parceiro (torre.gold_truckpag_pedagio).
//
// O QUE NAO EXISTE AQUI (e por que):
//   - comparacao ANP: e referencia de preco de COMBUSTIVEL, nao faz sentido
//     em pedagio (tarifa e' fixa por praca, nao negociavel)
//   - custo/km e km/L: a tabela de pedagio nao tem hodometro, entao nao da
//     pra derivar km. Custo/km unificado (combustivel+pedagio) era o que o
//     relatorio antigo misturado fazia -- ficou fora da separacao.
//   - coluna "Situacao": mesma decisao do combustivel (24/08/2026) --
//     relatorio informativo, nao prescritivo.
//
// runOnceForEachItem -> retorna OBJETO SOLTO (nao array).
// ===========================================================================

const d = $input.item.json;
const cfgNode = $('⚙️ Configurações').first().json;
const perNode = $('Calcular Período').first().json;

const cfg = {
  top_pracas: cfgNode.top_pracas || 8,
  modo_producao: cfgNode.modo_producao || false,
  email_teste: cfgNode.email_teste || 'gabriel.brittes@gritsch.com.br',
};
const per = { dataRef: perNode.dataRef || 'Semana Atual' };

const emailFinal = cfg.modo_producao ? (d.email_gestor || cfg.email_teste) : cfg.email_teste;

// CC identico ao telemetria/combustivel: email_cc + cc_regional + cc_global,
// deduplicado e separado por virgula.
const ccParts = [];
if (d.email_cc) ccParts.push(d.email_cc);
if (d.cc_regional) ccParts.push(d.cc_regional);
if (d.cc_global) ccParts.push(d.cc_global);
const ccMerged = ccParts.join(';').split(/[;,]+/).map(s => s.trim()).filter(Boolean)
  .filter((v, i, a) => a.indexOf(v) === i).join(',');
const ccFinal = cfg.modo_producao ? ccMerged : '';

// --- Paleta TruckPag --------------------------------------------------------
const VERDE       = '#00B140';
const VERDE_ESC   = '#067A34';
const GRAFITE     = '#1D2321';
const CINZA       = '#5B645F';
const LINHA       = '#DCE3DE';
const FUNDO       = '#F4F7F5';
const BRANCO      = '#FFFFFF';

const F_DISPLAY = "'Manrope','Segoe UI',Arial,sans-serif";
const F_CORPO   = "'IBM Plex Sans','Segoe UI',Arial,sans-serif";

// Logo TruckPag como anexo inline (CID) -- o n8n da cid=nomeDaPropriedade
// binaria a todo item de options.attachments. Ver memoria do projeto.
const TRUCKPAG_LOGO_B64 = '';
const GRITSCH_LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';
const AZUL_GRITSCH = '#213035';

// --- Formatadores -----------------------------------------------------------
const moeda = (val) => {
  const n = parseFloat(val) || 0;
  return 'R$ ' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};
const numBr = (val, dec = 0) => {
  const n = parseFloat(val) || 0;
  return n.toLocaleString('pt-BR', { minimumFractionDigits: dec, maximumFractionDigits: dec });
};
const fmtDec = (v, dec = 2) => {
  if (v === null || v === undefined || isNaN(parseFloat(v))) return 'N/D';
  return parseFloat(v).toFixed(dec).replace('.', ',');
};
const cleanCityUf = (cidade, uf) => {
  let c = (cidade || 'N/D').trim().replace(/S\?O/gi, 'São').replace(/SAO/gi, 'São').replace(/\?/g, '');
  c = c.toLowerCase().replace(/(?:^|\s|\/)\S/g, a => a.toUpperCase())
    .replace(/Sao /gi, 'São ').replace(/Candoi/gi, 'Candói').replace(/Prudentopolis/gi, 'Prudentópolis')
    .replace(/Corbelia/gi, 'Corbélia').replace(/Mambore/gi, 'Mamborê');
  return c + ' / ' + (uf || 'N/D').toUpperCase();
};

const calcVar = (atual, ant, fmt = moeda) => {
  const vAtu = parseFloat(atual) || 0, vAnt = parseFloat(ant) || 0;
  if (vAnt === 0) return { atualStr: fmt(vAtu), antStr: 'N/D', pctStr: 'N/D' };
  const pct = ((vAtu - vAnt) / vAnt) * 100;
  return { atualStr: fmt(vAtu), antStr: fmt(vAnt), pctStr: (pct > 0 ? '+' : '') + pct.toFixed(1) + '%' };
};

// --- Dados ------------------------------------------------------------------
const gastoPedagio = parseFloat(d.total_gasto_pedagio || 0);
const gastoPedagioAnt = parseFloat(d.total_gasto_pedagio_ant || 0);
const passagens = parseInt(d.total_passagens || 0, 10);
const passagensAnt = parseInt(d.total_passagens_ant || 0, 10);
const ticket = parseFloat(d.ticket_medio || 0);
const ticketAnt = parseFloat(d.ticket_medio_ant || 0);
const veic = parseInt(d.qtd_veiculos_ativos || 0, 10);
const veicAnt = parseInt(d.qtd_veiculos_ativos_ant || 0, 10);

const frota = Array.isArray(d.frota_pedagio) ? d.frota_pedagio : [];
const pracas = Array.isArray(d.pedagio_pracas_utilizadas) ? d.pedagio_pracas_utilizadas : [];
const detalhe = Array.isArray(d.pedagios_detalhe) ? d.pedagios_detalhe : [];

// Gasto medio por veiculo: quanto cada veiculo que rodou custou em pedagio.
const gastoPorVeiculo = veic > 0 ? (gastoPedagio / veic) : 0;
const gastoPorVeiculoAnt = veicAnt > 0 ? (gastoPedagioAnt / veicAnt) : 0;

const kpiGasto = calcVar(gastoPedagio, gastoPedagioAnt, moeda);
const kpiPassagens = calcVar(passagens, passagensAnt, (v) => numBr(v, 0));
const kpiTicket = calcVar(ticket, ticketAnt, moeda);
const kpiVeic = calcVar(veic, veicAnt, (v) => numBr(v, 0));
const kpiPorVeiculo = calcVar(gastoPorVeiculo, gastoPorVeiculoAnt, moeda);

// --- Componentes de layout --------------------------------------------------
const linhaKpi = (indicador, kpi) =>
  '<tr>'
  + '<td style="padding:11px 16px;font-size:13px;color:' + GRAFITE + ';font-weight:600;'
  + 'border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + indicador + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;font-weight:700;color:' + GRAFITE + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.atualStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.antStr + '</td>'
  + '<td style="padding:11px 16px;text-align:right;font-size:13px;color:' + CINZA + ';'
  + 'border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + kpi.pctStr + '</td>'
  + '</tr>';

const th = (txt, align) =>
  '<th style="padding:10px 16px;text-align:' + (align || 'left') + ';font-size:11px;font-weight:700;'
  + 'text-transform:uppercase;letter-spacing:0.04em;color:' + BRANCO + ';background:' + VERDE + ';'
  + 'font-family:' + F_CORPO + '">' + txt + '</th>';

const faixaSecao = (titulo) =>
  '<tr><td style="padding:26px 32px 0"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + VERDE_ESC + ';border-radius:6px 6px 0 0;padding:10px 18px;'
  + 'font-size:13px;font-weight:700;color:' + BRANCO + ';text-transform:uppercase;letter-spacing:0.03em;'
  + 'font-family:' + F_CORPO + '">' + titulo + '</td></tr></table></td></tr>';

// Linha de TOTAL: so em tabela que e' recorte COMPLETO. Top N de pracas nao
// leva soma -- pareceria o total real da filial, e nao e'.
const linhaTotal = (celulas) =>
  '<tr>' + celulas.map((c, i) =>
    '<td style="padding:10px 16px;text-align:' + (i === 0 ? 'left' : 'right') + ';font-weight:800;'
    + 'color:' + GRAFITE + ';font-size:12px;background:' + FUNDO + ';border-top:1.6px solid ' + VERDE + ';'
    + 'font-variant-numeric:tabular-nums;font-family:' + F_CORPO + '">' + c + '</td>'
  ).join('') + '</tr>';

// --- Top 5 veiculos que mais gastaram em pedagio ----------------------------
const frotaOrdenada = frota.slice().sort((a, b) => (b.valor_total || 0) - (a.valor_total || 0));
const topGastos = frotaOrdenada.slice(0, 5);
let rowsTopGastos = '';
for (const v of topGastos) {
  const pass = parseInt(v.passagens || 0, 10);
  const ticketV = pass > 0 ? (parseFloat(v.valor_total || 0) / pass) : null;
  rowsTopGastos += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + v.placa + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(pass, 0) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(v.valor_total) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (ticketV != null ? moeda(ticketV) : 'N/D') + '</td>'
    + '</tr>';
}

// --- Pracas mais utilizadas (Top N) -----------------------------------------
const pracasOrdenadas = pracas.slice().sort((a, b) => (b.gasto || 0) - (a.gasto || 0));
let rowsPracas = '';
for (const p of pracasOrdenadas) {
  rowsPracas += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + (p.praca || 'Praça') + '</td>'
    + '<td style="padding:9px 16px;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + '">' + cleanCityUf(p.cidade, p.uf) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(p.passagens, 0) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.gasto) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(p.ticket_medio) + '</td>'
    + '</tr>';
}

// --- Frota completa em pedagio (com TOTAL) ----------------------------------
let rowsFrota = '';
for (const v of frotaOrdenada) {
  const pass = parseInt(v.passagens || 0, 10);
  const ticketV = pass > 0 ? (parseFloat(v.valor_total || 0) / pass) : null;
  rowsFrota += '<tr>'
    + '<td style="padding:9px 16px;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-family:' + F_CORPO + '">' + v.placa + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + numBr(pass, 0) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;font-weight:700;color:' + GRAFITE + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + moeda(v.valor_total) + '</td>'
    + '<td style="padding:9px 16px;text-align:right;color:' + CINZA + ';font-size:12px;border-bottom:1px solid ' + LINHA + ';font-variant-numeric:tabular-nums">' + (ticketV != null ? moeda(ticketV) : 'N/D') + '</td>'
    + '</tr>';
}
if (frotaOrdenada.length > 0) {
  rowsFrota += linhaTotal([
    'TOTAL · ' + frotaOrdenada.length + ' veículos', numBr(passagens, 0), moeda(gastoPedagio), moeda(ticket),
  ]);
}

// Faixa de contorno topografico -- identica ao combustivel.
function faixaTopografica(altura, corLinha) {
  let paths = '';
  const alturas = [0.30, 0.45, 0.58, 0.70, 0.80, 0.88];
  const opacidades = [0.55, 0.42, 0.32, 0.24, 0.16, 0.10];
  for (let i = 0; i < alturas.length; i++) {
    const y = Math.round(altura * alturas[i]);
    const amp = 10 - i;
    paths += '<path d="M-10 ' + y + ' Q 90 ' + (y - amp) + ' 190 ' + y + ' T 390 ' + y
      + ' T 590 ' + y + ' T 790 ' + y + '" fill="none" stroke="' + corLinha + '" '
      + 'stroke-opacity="' + opacidades[i] + '" stroke-width="1.6"/>';
  }
  return 'data:image/svg+xml;base64,' + Buffer.from(
    '<svg xmlns="http://www.w3.org/2000/svg" width="760" height="' + altura + '" preserveAspectRatio="none">' + paths + '</svg>'
  ).toString('base64');
}
const contornoTopo = faixaTopografica(72, VERDE);

// --- Documento --------------------------------------------------------------
const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
+ '<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@600;700;800&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">'
+ '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + F_CORPO + '">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
+ '<tr><td align="center">'
+ '<table width="760" cellpadding="0" cellspacing="0" style="max-width:760px;width:100%;'
+ 'background:' + BRANCO + ';border:1px solid ' + LINHA + ';border-radius:10px">'

+ '<tr><td style="background:' + FUNDO + ';border-radius:10px 10px 0 0;padding:0">'
+ '<img src="' + contornoTopo + '" width="760" height="72" style="display:block;width:100%;height:72px" alt="">'
+ '</td></tr>'
+ '<tr><td style="padding:20px 32px 18px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle">'
+ '<img src="cid:logo_truckpag" height="28" style="display:block;height:28px;width:auto" alt="TruckPag">'
+ '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:' + CINZA + ';margin-top:12px;font-family:' + F_CORPO + '">Torre de Controle · Pedágio · dados do parceiro</div>'
+ '<div style="font-size:21px;font-weight:800;color:' + GRAFITE + ';margin-top:3px;font-family:' + F_DISPLAY + '">' + (d.filial_nome || '—') + '</div>'
+ '</td>'
+ '<td valign="middle" align="right">'
+ '<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:' + CINZA + ';font-family:' + F_CORPO + '">Fechamento</div>'
+ '<div style="font-size:13px;color:' + GRAFITE + ';margin-top:6px;font-family:' + F_CORPO + '">' + per.dataRef + '</div>'
+ '</td>'
+ '</tr></table></td></tr>'
+ '<tr><td style="border-bottom:1px solid ' + LINHA + '"></td></tr>'

+ '<tr><td style="padding:22px 32px 0">'
+ '<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-radius:8px;overflow:hidden">'
+ '<tr>' + th('Indicador') + th('Atual', 'right') + th('Semana anterior', 'right') + th('Variação', 'right') + '</tr>'
+ linhaKpi('Gasto total com pedágio', kpiGasto)
+ linhaKpi('Passagens em praças', kpiPassagens)
+ linhaKpi('Ticket médio por passagem', kpiTicket)
+ linhaKpi('Veículos que passaram em pedágio', kpiVeic)
+ linhaKpi('Gasto médio por veículo', kpiPorVeiculo)
+ '</table></td></tr>'

+ (topGastos.length > 0 ? (
  faixaSecao('Top 5 maiores gastos em pedágio')
  + '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
  + '<tr>' + th('Placa') + th('Passagens', 'right') + th('Gasto', 'right') + th('Ticket médio', 'right') + '</tr>'
  + rowsTopGastos + '</table></td></tr>'
) : '')

+ (pracasOrdenadas.length > 0 ? (
  faixaSecao('Praças mais utilizadas · Top ' + cfg.top_pracas)
  + '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
  + '<tr>' + th('Praça / Operadora') + th('Cidade / UF') + th('Passagens', 'right') + th('Gasto', 'right') + th('Ticket médio', 'right') + '</tr>'
  + rowsPracas + '</table></td></tr>'
) : '')

+ (frotaOrdenada.length > 0 ? (
  faixaSecao('Frota completa em pedágio')
  + '<tr><td style="padding:0 32px"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ' + LINHA + ';border-top:none;border-radius:0 0 6px 6px">'
  + '<tr>' + th('Placa') + th('Passagens', 'right') + th('Gasto', 'right') + th('Ticket médio', 'right') + '</tr>'
  + rowsFrota + '</table></td></tr>'
) : '')

+ '<tr><td style="padding:22px 32px 0">'
+ '<div style="background:' + FUNDO + ';border:1px solid ' + LINHA + ';border-radius:6px;padding:14px 18px;font-size:12px;color:' + CINZA + ';font-family:' + F_CORPO + '">'
+ '<strong style="color:' + GRAFITE + '">Anexos:</strong> extrato completo em CSV — '
+ '<code style="background:' + BRANCO + ';border:1px solid ' + LINHA + ';border-radius:3px;padding:1px 5px">Frota_Pedagio_' + (d.filial_nome || 'Filial') + '.csv</code>, '
+ '<code style="background:' + BRANCO + ';border:1px solid ' + LINHA + ';border-radius:3px;padding:1px 5px">Pracas_' + (d.filial_nome || 'Filial') + '.csv</code> e '
+ '<code style="background:' + BRANCO + ';border:1px solid ' + LINHA + ';border-radius:3px;padding:1px 5px">Passagens_' + (d.filial_nome || 'Filial') + '.csv</code>.'
+ '</div></td></tr>'

// Rodape: padrao Gritsch, igual ao rastreador e ao combustivel.
+ '<tr><td style="padding:24px 32px;background:' + AZUL_GRITSCH + ';border-radius:0 0 10px 10px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle">'
+ '<img src="' + GRITSCH_LOGO_BRANCA + '" width="110" style="display:block;width:110px;height:auto" alt="Gritsch">'
+ '</td>'
+ '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7;font-family:' + F_CORPO + '">'
+ 'Relatório automático da Torre de Controle · semanal<br>'
+ 'Dados fornecidos pela TruckPag<br>'
+ 'torredecontrole@gritsch.com.br'
+ '</td>'
+ '</tr></table></td></tr>'

